"""Exact polyline tables for the original-span path representation.

An offset edge interpolates the adjacent line-intersection (miter) vectors.
It remains parallel to its source segment and joins at the authored bend.
The local guard rejects reversed offset segments and excessive miters; global
overlap still belongs to the existing complete surface/perimeter checks.
"""
import bpy
from . import curved_corner_nodes as c


def prepare(*, endpoint_tangents=False, endpoint_frames=False):
    name = 'Prochitecture Streets / Original exact polyline table v1'
    if endpoint_tangents:
        name += ' / Declared endpoint tangents v1'
    if endpoint_frames:name += ' / Declared endpoint miters v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    g.socket('Geometry', 'NodeSocketGeometry')
    g.socket('Reverse', 'NodeSocketBool', default=False)
    g.socket('Width', 'NodeSocketFloat', default=6.)
    g.socket('Offset', 'NodeSocketFloat', default=0.)
    if endpoint_tangents:
        for side in ('Start', 'End'):
            g.socket('Use '+side+' Tangent', 'NodeSocketBool', default=False)
            g.socket(side+' Tangent', 'NodeSocketVector')
    if endpoint_frames:
        for side in ('Start','End'):
            g.socket('Use '+side+' Profile Axis','NodeSocketBool',default=False)
            g.socket(side+' Profile Axis','NodeSocketVector')
    for key, kind in (('Geometry', 'NodeSocketGeometry'), ('Length', 'NodeSocketFloat'),
                      ('Valid', 'NodeSocketBool'), ('Weighted', 'NodeSocketBool')):
        g.socket(key, kind, 'OUTPUT')
    inp = g.node('NodeGroupInput'); src = inp.outputs['Geometry']
    count = c._count(g, src); last = count-1.
    i = c.V(g, g.node('GeometryNodeInputIndex').outputs[0])
    at = c.choose(g, inp.outputs['Reverse'], last-i, i, 'INT')
    geo = g.setpos(c._line(g, c.bounded(g, count, 2., c.MAX_CONTROLS)),
                   c._sample(g, src, g.position(), at, 'FLOAT_VECTOR'))
    p = c._vec(g, g.position())
    prev = c._vec(g, c._sample(g, geo, g.position(), g.math('MAXIMUM', 0., i-1.), 'FLOAT_VECTOR'))
    nxt = c._vec(g, c._sample(g, geo, g.position(), g.math('MINIMUM', last, i+1.), 'FLOAT_VECTOR'))
    incoming, outgoing = c._sub(p, prev), c._sub(nxt, p)
    before, after = c._length(g, incoming), c._length(g, outgoing)
    tin, tout = c._unit(g, incoming), c._unit(g, outgoing)
    first = g.math('LESS_THAN', i, .5); final = g.math('GREATER_THAN', i, last-.5)
    denominator = 1.+c._dot(tin, tout)
    miter = c._scale(c._add(c._right(tin), c._right(tout)),
                     g.math('DIVIDE', 1., g.math('MAXIMUM', denominator, .001)))
    miter = c._pick(g, first, c._right(tout), miter)
    miter = c._pick(g, final, c._right(tin), miter)
    tangent = c._pick(g, final, tin, tout)
    valid = g.math('GREATER_THAN', count, 1.5)*g.math('LESS_THAN', count, c.MAX_CONTROLS+.5)
    ok = c.choose(g, first, 1., g.math('GREATER_THAN', before, 1e-4))
    # Same miter-angle bound as the established exact-polyline sweep.
    ok = ok*c.choose(g, first+final, 1., g.math('GREATER_THAN', denominator, .125-1e-8))
    z = g.separate(g.position())[2]
    ok = ok*g.math('LESS_THAN', g.math('ABSOLUTE', z), 1e-5)
    ok = ok*g.math('LESS_THAN', c._length(g, p), 1e6)
    valid = valid*c._stat(g, geo, ok)
    size = g.node('GeometryNodeAttributeDomainSize'); size.component = 'MESH'
    g.bind(src, size.inputs['Geometry'])
    edges = g.node('GeometryNodeInputMeshEdgeVertices')
    adjacent = g.math('ABSOLUTE', c.V(g, edges.outputs['Vertex Index 1'])-c.V(g, edges.outputs['Vertex Index 2']))
    degree = g.node('GeometryNodeInputMeshVertexNeighbors')
    valid = valid*c._stat(g, src, g.math('COMPARE', adjacent, 1.), domain='EDGE')
    valid = valid*g.math('COMPARE', size.outputs['Edge Count'], last)*g.math('LESS_THAN', size.outputs['Face Count'], .5)
    valid = valid*c._stat(g, src, g.math('COMPARE', degree.outputs['Vertex Count'], c.choose(g, first+final, 1., 2.)))
    if endpoint_tangents:
        for side, at in (('Start', 0), ('End', last)):
            actual = c._vec(g, c._sample(g, geo, g.xyz(*tangent), at, 'FLOAT_VECTOR'))
            requested = c._vec(g, inp.outputs[side+' Tangent'])
            agrees = g.math('GREATER_THAN', c._length(g, requested), 1e-5)
            agrees = agrees*g.math('LESS_THAN', c._length(g, c._sub(actual, c._unit(g, requested))), 1e-5)
            valid = valid*c.choose(g, inp.outputs['Use '+side+' Tangent'], agrees, 1.)
    if endpoint_frames:
        # A declared neighboring Exact Street supplies the same offset-line
        # intersection frame as an interior bend. It changes the transverse
        # row only; the authored centerline and its one-sided tangent stay put.
        # Unit normal projection retains the physical width of this leg.
        for side,at,selection in (('Start',0,first),('End',last,final)):
            axis=c._vec(g,inp.outputs[side+' Profile Axis'])
            actual=c._vec(g,c._sample(g,geo,g.xyz(*tangent),at,'FLOAT_VECTOR'))
            unit_offset=g.math('LESS_THAN',g.math('ABSOLUTE',c._dot(axis,c._right(actual))-1.),1e-5)
            # denominator >= 1/8 at ordinary bends means |miter| <= 4.
            bounded=g.math('LESS_THAN',c._length(g,axis),4.+1e-6)
            planar=g.math('LESS_THAN',g.math('ABSOLUTE',g.separate(inp.outputs[side+' Profile Axis'])[2]),1e-5)
            enabled=inp.outputs['Use '+side+' Profile Axis']
            valid=valid*c.choose(g,enabled,unit_offset*bounded*planar,1.)
            miter=c._pick(g,c.V(g,enabled)*selection,axis,miter)
    width, offset = c.V(g, inp.outputs['Width']), c.V(g, inp.outputs['Offset'])
    valid = valid*g.math('GREATER_THAN', width, 1e-5)*g.math('LESS_THAN', width, 1e5)
    valid = valid*g.math('LESS_THAN', g.math('ABSOLUTE', offset), 1e5)
    geo = c._store(g, geo, 'st_cc_miter', g.xyz(*miter), 'FLOAT_VECTOR')
    current = c._vec(g, c.named(g, 'st_cc_miter', 'FLOAT_VECTOR'))
    following = c._vec(g, c._read(g, geo, 'st_cc_miter', g.math('MINIMUM', last, i+1.), 'FLOAT_VECTOR'))
    rate = c._scale(c._sub(following, current), g.math('DIVIDE', 1., g.math('MAXIMUM', after, 1e-12)))
    stretch = c._dot(rate, tout)
    # Along either offset edge the derivative is constant on the entire
    # segment. Check both extremes of the physical transverse interval.
    from .interpolating_curve_nodes import OFFSET_JACOBIAN_MARGIN
    positive = 1.
    for sign in (-.5, .5):
        positive = positive*g.math('GREATER_THAN', 1.+(offset+sign*width)*stretch, OFFSET_JACOBIAN_MARGIN)
    valid = valid*c._stat(g, geo, c.choose(g, final, 1., positive))
    prefix = g.node('GeometryNodeAccumulateField'); prefix.domain = 'POINT'; prefix.data_type = 'FLOAT'
    g.bind(before, prefix.inputs['Value'])
    for key, value, kind in (
        ('knot', prefix.outputs['Leading'], 'FLOAT'), ('p', g.position(), 'FLOAT_VECTOR'),
        ('tangent', g.xyz(*tangent), 'FLOAT_VECTOR'), ('a', g.xyz(*outgoing), 'FLOAT_VECTOR'),
        ('b', g.xyz(), 'FLOAT_VECTOR'), ('c', g.xyz(), 'FLOAT_VECTOR'), ('span', after, 'FLOAT'),
        ('miter_rate', g.xyz(*rate), 'FLOAT_VECTOR'), ('polyline', True, 'BOOLEAN')):
        geo = c._store(g, geo, 'st_cc_'+key, value, kind)
    geo = g.setpos(geo, g.xyz(c.named(g, 'st_cc_knot')))
    out = g.node('NodeGroupOutput')
    for key, value in (('Geometry', geo), ('Length', c._read(g, geo, 'st_cc_knot', last)),
                       ('Valid', valid), ('Weighted', False)):
        g.bind(value, out.inputs[key])
    return g.g
